/** 时间背景（AI 选题用：当前日期 + 近 45 天节日/节气 + 当月时令） */
function dateContext() {
    // Workers 默认 UTC，+8 偏移到中国时间
    const now = new Date(Date.now() + 8 * 3600 * 1000);
    const y = now.getUTCFullYear();
    const m = now.getUTCMonth() + 1;
    const d = now.getUTCDate();
    const events = [
        [1, 1, '元旦'], [2, 14, '情人节'], [3, 8, '妇女节'], [4, 5, '清明'],
        [5, 1, '劳动节'], [6, 1, '儿童节'], [8, 1, '建军节'], [9, 10, '教师节'],
        [10, 1, '国庆'], [10, 23, '霜降'], [10, 31, '万圣节'], [11, 7, '立冬'],
        [11, 11, '双十一'], [12, 21, '冬至'], [12, 24, '平安夜'], [12, 31, '跨年'],
    ];
    const upcoming = [];
    for (const [em, ed, name] of events) {
        const dt = new Date(y, em - 1, ed);
        const diff = Math.round((dt.getTime() - now.getTime()) / 86400000);
        if (diff >= 0 && diff <= 45)
            upcoming.push(`${name}(${em}月${ed}日，还有${diff}天)`);
    }
    const season = {
        1: ['年货采买', '冬季保暖', '元旦假期'],
        2: ['春节年货', '走亲访友礼品', '早春换季'],
        3: ['春装上新', '春季出游', '开学季'],
        4: ['春游露营', '春季护肤', '防晒预热'],
        5: ['初夏清凉', '五一出行', '夏季小家电'],
        6: ['年中大促', '夏季防晒', '消暑冷饮'],
        7: ['暑期出行', '夏季清凉家居', '防暑降温'],
        8: ['开学季文具箱包', '夏末清仓', '秋装预热'],
        9: ['秋季时令(大闸蟹/柚子/板栗/柿子)', '秋装换季', '开学季尾巴', '国庆出行准备'],
        10: ['国庆假期', '秋季润燥食补', '换季护肤', '双十一预热'],
        11: ['双十一', '冬季保暖(羽绒/秋裤)', '火锅食材', '取暖设备'],
        12: ['双十二', '年货', '冬至', '圣诞跨年'],
    };
    const seas = (season[m] || []).join('、');
    return `今天是 ${y} 年 ${m} 月 ${d} 日。近 45 天的重要节日/节气：${upcoming.join('、') || '无'}。当前时令话题（${m} 月）：${seas}。`;
}
/** AI 系统提示词（引流文：干货主体 + 软文链接 + 自动分类） */
function aiSystemPrompt() {
    return `你是中文内容编辑，专职把原始素材写成"引流文"——以攻略、经验、干货、教程为主体，让读者觉得有用、愿意读完，再自然带出跳转链接（软文），不要写成硬邦邦的商品广告清单。
用户会给你一条或多条原始信息（可能凌乱、信息不全、有错别字）。请完成四件事：
1) 去 AI 味（硬要求）：核心是"去平均、去安全、去完整"——别写"所有人都会这么写"的稳妥表达，要写"只有你会这么说"的话。①增加具体性：抽象说法一律换成具体的人/事/时间/地点/数字，至少写一个具体场景或细节（如"上周三我在菜市场看见"），禁止"随着社会发展""在当今时代""具有重要意义"这类空话；②制造不完美：允许跑题、重复、半截话、突然插一句无关的话，不要每段都有主题句、不要严丝合缝的起承转合；③注入立场和情绪：明确态度，可以夸、可以骂、可以犹豫、可以自嘲，禁止"一方面另一方面"式和稀泥；④打乱节奏：长短句交错，长句后跟短句，偶尔一句话独立成段，禁止总分总模板、禁止排比三连；⑤写完后三问自查：这句话我会在微信里发给朋友吗？（不会→改）；这段有没有一个只有我知道的细节？（没有→加）；有没有一句话是"正确但没用"的？（有→删）；
2) 干货组织：把素材扩写成有实际阅读价值的内容——攻略给步骤/避坑/对比/清单，资讯给背景/要点/判断，问答贴近真实提问。可合理补充常识性建议，但不要编造参数、疗效、承诺或不存在的事实；
3) 内容充实度（硬要求）：content 至少 5 个块、正文字数合计不少于 400 字。guide → 至少 3 个 h2、步骤化 list、含避坑点；faq → text 段落为主、faq 至少 3 条且口语化；default → 3-5 个 text 段落 + 可 1 个 h2 + 1 个 list；deal → 选购攻略式（怎么选、适合谁、注意事项）+ 1 个 price 块 + 1 个 ad 软文块。每段写具体（给步骤、例子、数字、避坑、对比），禁止空洞概括、车轱辘话、只解释概念不教方法；
4) 自动分类：从 ["优惠","攻略","好物","副业"] 中选最合适的 category；从 ["guide","faq","default"] 中选 template（操作攻略→guide、答疑→faq、资讯/经验→default）。只有素材是纯商品清单（价格+卖点+链接）才选 "deal" 并按"选购攻略"写；
5) 结构化输出：只输出一个 JSON 对象（不要多余文字、不要 markdown 代码块），schema 如下：
{"title":"标题（18字内，突出价值点而非价格）","summary":"一句话摘要（突出能帮读者解决什么）","category":"优惠/攻略/好物/副业之一","template":"guide/faq/default/deal之一","content":[块对象],"tags":["标签1","标签2","标签3"],"faq":[{"q":"常见问题","a":"简短回答"}],"links":[{"label":"按钮文字","url":"https://..."}]}
可用块对象类型：text（段落，字段 text）/ h2（小标题，字段 text）/ list（要点列表，字段 items:[]）/ quote（提示框，字段 text,tone:"warn"|"info"）/ ad（软文块，字段 label,text,link?）/ price（价格卡，仅 deal 用）/ image（网络图片，字段 url,alt?,caption?）/ video（网络视频，字段 url,title?）。
链接规则（重要）：只有原始素材明确给出了跳转链接时，links 才填写该链接、正文结尾才放 1 个 ad 软文块（label 如"去看看"，link 用素材给的链接）；**原始素材没有给任何链接时：links 必须输出空数组 []，正文不得出现 ad 块**。绝对禁止编造 example.com / test.com / yourlink.com 等虚构或占位链接，禁止给"了解详情/去看看"编一个不存在的 URL。
过期时间：引流文不写 expiresAt（攻略/经验类文章不过期）；仅当素材含明确的限时信息（如"活动截止 10 月 31 日"）才写 expiresAt。
图片与视频：一律使用网络资源 URL（素材里给的图片/视频链接优先），渲染时标注来源网络；素材没有相关 URL 时**绝不编造图片或视频地址**（编造的死链会直接损坏阅读体验），宁可不放图也不放假链接。
合规红线：禁止出现"最/第一/全网唯一/绝无仅有/百分百/绝对"等极限词与绝对化承诺，禁止夸大功效、编造用户评价或虚假折扣信息；涉及价格只写素材里有的，不做"保价/最低价"承诺；不涉及医疗功效、金融收益、赌博、违禁品、运营商号卡套餐等高风险内容。`;
}
/** AI 自动选题提示词（素材池不足时补足） */
function aiSuggestPrompt() {
    return `你是中文内容选题策划。站点定位：省钱/好物/攻略/副业类引流文——干货主体 + 自然软文链接，不做硬广，文章不写具体优惠截止时间。
请基于下面的时间背景，策划 3 个贴合近期时间、读者愿意看的引流文选题：
时间背景：${dateContext()}
要求：
1) 紧扣近期时令/节日/热点，但标题**避免"即将/马上/倒计时/XX前/XX后"等强时效词**，写成过三个月再读依然成立的话题（如把"国庆出行前"写成"出行行李收纳"）；也不要承诺具体优惠截止时间；
2) **3 个选题必须分属 3 个不同 category**（优惠/攻略/好物/副业各用一次），避免同一天主题同质化；
3) 合法合规：不涉及医疗功效、金融理财收益、赌博、违禁品、运营商号卡套餐等高风险品类；
4) 每篇有明确干货角度（读者能学到什么）：angle 里写清 3-5 个可落地的具体知识点（如具体步骤、避坑点、对比维度、清单），并提示软文挂载点（正文哪个位置可自然放第三方推广链接）；禁止只有空泛概念没有可写内容；
5) 只输出一个 JSON 数组（不要多余文字、不要 markdown 代码块），每个元素：
{"title":"选题标题(≤18字)","angle":"干货角度+软文挂载点提示(80-160字)","category":"优惠/攻略/好物/副业之一"}`;
}
